# Flugfunk-5. Kein Mesh. prepper-sdr bleibt laufen.
from __future__ import annotations
import base64, hashlib, json, os, re, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
FULL = Path("/home/fmg/fullcheck.sh")
FEST = {
    "flugfunk.py": ("1ff7ba8ea05367d4", 77042),
    "dashboard.py": ("3351c6fd29c51746", 1387903),
    "pushover_push.py": ("3916f7d880b13569", 12237),
    "prepper_sdr.py": ("9519012e7a1142ba", 779574),
}

def load():
    return json.loads(PAYLOAD_TEXT)

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def paare():
    return [(base64.b64decode(x['old']), base64.b64decode(x['new'])) for x in load()['pairs']]

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin Minute %02d" % jetzt.minute

def paare():
    return [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in load()["pairs"]]

def verwandle(data, pairs):
    neu = data
    for old, neu_s in pairs:
        if neu.count(neu_s) >= 1 and neu.count(old) == 0:
            continue
        if neu.count(old) != 1 or neu.count(neu_s) != 0 or old in neu_s:
            raise RuntimeError("Stelle")
        vor = neu
        neu = neu.replace(old, neu_s, 1)
        if neu.replace(neu_s, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu

def fullcheck_neu(text: str) -> str:
    if "flugfunk-5" in text and 'FC_VERSION="2.2"' in text and "/funk433" not in text:
        return text
    neu = text
    getroffen = False
    for alt in ('FC_VERSION="2.1.1"', 'FC_VERSION="2.0.2"'):
        if neu.count(alt) == 1:
            neu = neu.replace(alt, 'FC_VERSION="2.2"', 1)
            getroffen = True
            break
    if not getroffen:
        raise RuntimeError("version")
    if "Basis flugfunk-5" not in neu and "# fullcheck.sh - Gesamtpruefung" in neu:
        neu = neu.replace("# fullcheck.sh - Gesamtpruefung", "# fullcheck.sh - Gesamtpruefung, Basis flugfunk-5.", 1)
    neu2, n = re.subn(r'DASH_SHA16="\$\{FC_DASH_SHA16:-[0-9a-f]{16}\}"', 'DASH_SHA16="${FC_DASH_SHA16:-3351c6fd29c51746}"', neu, count=1)
    if n != 1:
        raise RuntimeError("dashsha")
    neu = neu2
    if "PUSH_SHA16=" not in neu:
        neu = neu.replace(
            'DASH_SHA16="${FC_DASH_SHA16:-3351c6fd29c51746}"',
            'DASH_SHA16="${FC_DASH_SHA16:-3351c6fd29c51746}"\nPUSH_SHA16="${FC_PUSH_SHA16:-3916f7d880b13569}"',
            1,
        )
    if neu.count(" /funk433") != 1:
        raise RuntimeError("funk433")
    neu = neu.replace(" /funk433", "", 1)
    if "/api/flugfunk" not in neu.split("flugfunk-5: Kachel", 1)[0]:
        if neu.count("/api/sdr/status)") != 1:
            raise RuntimeError("seiten")
        neu = neu.replace("/api/sdr/status)", "/api/sdr/status /api/flugfunk)", 1)
    if neu.count('RNAME="Stick 3 Hobby2"') != 1:
        raise RuntimeError("hobby2")
    neu = neu.replace('RNAME="Stick 3 Hobby2"', 'RNAME="Stick 3 Flugfunk"', 1)
    if 'sdr_dev "$STICK3_SN" "Stick 3 (hobby2)" warn' in neu:
        neu = neu.replace('sdr_dev "$STICK3_SN" "Stick 3 (hobby2)" warn', 'sdr_dev "$STICK3_SN" "Stick 3 (Flugfunk EDDN)" warn', 1)
    neu = neu.replace("SDR Stick 3 Hobby2", "SDR Stick 3 Flugfunk")
    neu = neu.replace("Stick 3 = Pinneberg/SpyVerter", "Stick 3 = Flugfunk EDDN")
    alt_hinweis = "Betroffenen Stick im Dashboard (/funk) ansehen."
    if neu.count(alt_hinweis) != 1:
        raise RuntimeError("hinweis")
    neu = neu.replace(alt_hinweis, "Stick 2 auf /funk, Flugfunk auf /adsb ansehen.", 1)
    alt_rot = "Stick/Empfang pruefen (Dashboard /funk); prepper-sdr-Journal lesen."
    if neu.count(alt_rot) != 1:
        raise RuntimeError("rot")
    neu = neu.replace(alt_rot, "Stick 2 auf /funk, Flugfunk auf /adsb pruefen; prepper-sdr-Journal lesen.", 1)
    neu = neu.replace('skip "Seitentest (26 Seiten/APIs)"', 'skip "Seitentest (Seiten/APIs)"', 1)
    if "flugfunk-5: Kachel" not in neu:
        anker = "  # --- SDR-Watchdog (Datenlage der Sticks, nur lesen)\n"
        if anker not in neu:
            raise RuntimeError("watchdog")
        zusatz = base64.b64decode(load()["fc_block"]).decode()
        neu = neu.replace(anker, zusatz + anker, 1)
    if "pushover_push.py sha16" not in neu:
        mark = '  else warn "dashboard.py sha16"'
        if mark not in neu:
            raise RuntimeError("push")
        neu = neu.replace(mark, (
            '  PUSHF="$APP/pushover_push.py"\n'
            '  if [[ -r "$PUSHF" ]]; then PSH="$(sha16_of "$PUSHF")";\n'
            '    if [[ "$PSH" == "$PUSH_SHA16" ]]; then ok "pushover_push.py sha16" "$PSH = Soll nach flugfunk-5";\n'
            '    else warn "pushover_push.py sha16" "$PSH, Soll $PUSH_SHA16" "Soll nach flugfunk-5."; fi\n'
            '  else warn "pushover_push.py" "nicht lesbar" "Pfad pruefen."; fi\n'
            + mark
        ), 1)
    neu = neu.replace("Soll (Pi-Stand nach commit47)", "Soll (Pi-Stand nach flugfunk-5)", 1)
    neu = neu.replace('section "Patch-Stand (Soll: AUDIT-STAND.md, nach commit47)"', 'section "Patch-Stand (Soll nach flugfunk-5)"', 1)
    if "/funk433" in neu or 'FC_VERSION="2.2"' not in neu or "Stick 3 Flugfunk" not in neu:
        raise RuntimeError("vollstaendig")
    return neu

def sichern(path, data, ende):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(Path(path).parent.glob(Path(path).name + ".bak-" + ende + "-*"))
    bak = Path(str(path) + ".bak-" + ende + "-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path, data, ende):
    path = Path(path)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o755
    tmp = path.with_name("." + path.name + ".tmp-" + ende)
    if tmp.exists():
        raise RuntimeError("temporaer")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner, dry, kein, jetzt=None, hashcheck=True, full_hash=""):
    print("===== SCHRITT PAKETE, dieses Skript installiert nichts =====")
    print("rtl_airband bleibt /usr/local/bin/rtl_airband")
    print("===== ENDE SCHRITT PAKETE =====")
    ordner = Path(ordner)
    blobs = {}
    for name, (kopf, laenge) in FEST.items():
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            if not hashcheck and name != "flugfunk.py":
                continue
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
        if hashcheck and (not sha(data).startswith(kopf) or len(data) != laenge):
            print("STOP: %s ist nicht der Stand nach apply-flugfunk-4" % name)
            return 2
    fc = FULL if hashcheck else (ordner / "fullcheck.sh")
    if fc.is_symlink() or not fc.is_file():
        print("STOP: fullcheck.sh fehlt")
        return 2
    fc_alt = fc.read_bytes()
    live = sha(fc_alt)
    print("fullcheck.sh sha256 %s sha16 %s bytes %d" % (live, live[:16], len(fc_alt)))
    if full_hash:
        if live != full_hash.strip().lower():
            print("STOP: --fullcheck-hash passt nicht")
            print("Live-Hash sha256 %s" % live)
            return 2
    elif hashcheck:
        print("STOP: Hash von fullcheck.sh ist nicht hinterlegt. Nichts geschrieben.")
        print("Live-Hash sha256 %s" % live)
        print("Erneut mit --fullcheck-hash %s wenn das die Datei 2.1.1 ist." % live)
        return 2
    try:
        ziel_fc = fullcheck_neu(fc_alt.decode("utf-8")).encode("utf-8")
        ziel_ff = verwandle(blobs["flugfunk.py"], paare())
    except (RuntimeError, UnicodeError) as exc:
        print("STOP: Stelle unbekannt (%s). Nichts geschrieben." % type(exc).__name__)
        return 2
    if hashcheck:
        compile(ziel_ff, "flugfunk.py", "exec")
    print("flugfunk.py endstand sha16 %s bytes %d" % (sha(ziel_ff)[:16], len(ziel_ff)))
    print("fullcheck.sh endstand sha16 %s bytes %d" % (sha(ziel_fc)[:16], len(ziel_fc)))
    if blobs["flugfunk.py"] == ziel_ff and fc_alt == ziel_fc:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        if blobs["flugfunk.py"] != ziel_ff:
            sichern(ordner / "flugfunk.py", blobs["flugfunk.py"], "flugfunk5")
            schreiben(ordner / "flugfunk.py", ziel_ff, "flugfunk5")
        sichern(fc, fc_alt, "fullcheck")
        schreiben(fc, ziel_fc, "fullcheck")
    except (OSError, RuntimeError):
        print("STOP beim Schreiben")
        return 3
    print("geschrieben. fullcheck 2.2. prepper-sdr bleibt laufen.")
    if kein or ordner != DASH:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest():
    assert fenster(__import__("datetime").datetime(2026, 11, 21, 12, 5))[0]
    assert not fenster(__import__("datetime").datetime(2026, 11, 21, 12, 4))[0]
    roh = open("/tmp/ff5-fixture.sh").read() if False else FIXTURE
    neu = fullcheck_neu(FIXTURE)
    assert 'FC_VERSION="2.2"' in neu and "/funk433" not in neu
    assert "3351c6fd29c51746" in neu and "3916f7d880b13569" in neu
    assert "Stick 3 Flugfunk" in neu and "Flugfunk EDDN" in neu
    assert "/api/flugfunk" in neu and "flugfunkBox" in neu and "Basis flugfunk-5" in neu
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk5-"))
    (ordner / "fullcheck.sh").write_text(FIXTURE)
    (ordner / "flugfunk.py").write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, False, True, __import__("datetime").datetime(2026, 11, 21, 12, 12), False, "deadbeef") == 2
    assert (ordner / "fullcheck.sh").read_text() == FIXTURE
    live = sha(FIXTURE.encode())
    assert apply_dir(ordner, False, True, __import__("datetime").datetime(2026, 11, 21, 12, 4), False, live) == 2
    assert (ordner / "fullcheck.sh").read_text() == FIXTURE
    (ordner / "flugfunk.py").write_bytes(b"\n".join(a for a, _b in paare()))
    assert apply_dir(ordner, True, True, __import__("datetime").datetime(2026, 11, 21, 12, 12), False, live) == 0
    assert (ordner / "fullcheck.sh").read_text() == FIXTURE
    assert apply_dir(ordner, False, True, __import__("datetime").datetime(2026, 11, 21, 12, 12), False, live) == 0
    assert b"2.2" in (ordner / "fullcheck.sh").read_bytes() and b"funk433" not in (ordner / "fullcheck.sh").read_bytes()
    ns = {"__name__": "flugfunk"}
    exec(compile(base64.b64decode(load()["flugfunk_neu"]), "flugfunk.py", "exec"), ns)
    bild = ns["karte_punkte"]([
        {"icao": "FERN", "lat": 48.0, "lon": 8.0},
        {"icao": "NAH", "lat": 49.55, "lon": 11.12},
        {"icao": "AKT", "lat": 50.2, "lon": 8.7},
    ], "AKT", "EDDN")
    assert all(p["icao"] != "FERN" for p in bild["punkte"])
    assert any(p["aktiv"] and p["icao"] == "AKT" for p in bild["punkte"])
    adsb = ns["funk_seite"]("<html><body></body></html>", "/adsb")
    assert ns["fullcheck_blatt"]("/adsb", adsb) == ""
    assert ns["fullcheck_blatt"]("/funk", ns["funk_seite"](adsb, "/funk")) == ""
    _de, en = ns["deutsch"]("alpha bravo alpha bravo descend")
    assert en.count("alpha bravo") == 1
    print("selftest ok")
    return 0

