def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    full_hash = ""
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--fullcheck-hash":
            i += 1
            full_hash = args[i]
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein, full_hash=full_hash)


